def remove_dups_buggy(L1, L2):
    for item in L1:
        if item in L2:
            L1.remove(item)
    return L1

L1 = [1, 2, 3, 4]
L2 = [1, 2, 5, 6]
print(f'Result (buggy): {remove_dups_buggy(L1, L2)}')

def remove_dups_correct(L1, L2):
    L1copy = L1[:]
    for item in L1copy:
        if item in L2:
            L1.remove(item)
    return L1

L1 = [1, 2, 3, 4]
L2 = [1, 2, 5, 6]
print(f'Result (correct): {remove_dups_correct(L1, L2)}')
